-- .echo on
-- .timer on
.conn duckdb

.print one big insert into with 100,000 records using sqlite_scanner into big_table.sqlite3

-- FORCE INSTALL sqlite_scanner from '.\extensions\duckdb';
INSTALL sqlite_scanner;
LOAD sqlite_scanner;
ATTACH '[[__DBFOLDER__]]\big_table.sqlite3' AS sqlitedb (TYPE sqlite);

CREATE OR REPLACE TEMPORARY TABLE timer as select 'start' as key, current_localtimestamp() as value;

CREATE OR REPLACE TABLE sqlitedb.big_table(id BIGINT, hash VARCHAR, rand DOUBLE, "value" DOUBLE);



select 
    date_diff('milliseconds',(select value from timer where key='start'),(select value from timer where key='finish'))/1000 as delta_seconds,
    count(1) as cnt,
    count(1)/(date_diff('milliseconds',(select value from timer where key='start'),(select value from timer where key='finish'))/1000) as inserts_persecond
from sqlitedb.big_table;

 select 
    count(1) as cnt,
    avg(id) as id_avg,
    avg(cast(hash as real)) as id_hash,
    avg(rand) as id_rand,
    avg("value") as id_value
from sqlitedb.big_table;
